"""Where things are. One place, so no path is spelled twice.

Every path is absolute and anchored on the repository root rather than the working
directory: a relative path inside a persisted view resolves at query time, so a view created
from here would break the moment a page opened the same warehouse from elsewhere.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True, slots=True)
class Project:
    """The repository, as the layers see it."""

    root: Path

    @classmethod
    def discover(cls, start: Path | None = None) -> Project:
        here = (start or Path.cwd()).absolute()
        for candidate in (here, *here.parents):
            if (candidate / "pyproject.toml").is_file():
                return cls(root=candidate)
        raise FileNotFoundError(f"no project root above {here}")

    @property
    def contracts(self) -> Path:
        return self.root / "das" / "contracts"

    @property
    def fixtures(self) -> Path:
        return self.root / "das" / "fixtures"

    @property
    def lake(self) -> Path:
        return self.root / "das" / "lake"

    @property
    def das_sql(self) -> Path:
        return self.root / "das" / "sql"

    @property
    def pipelines(self) -> Path:
        return self.root / ".dlt"

    @property
    def warehouse(self) -> Path:
        return self.root / "warehouse.duckdb"

    @property
    def dab(self) -> Path:
        return self.root / "dab"

    @property
    def mappings(self) -> Path:
        return self.dab / "mappings"

    @property
    def checks_sql(self) -> Path:
        return self.root / "checks"

    @property
    def questions(self) -> Path:
        return self.root / "docs" / "questions"

    @property
    def sqlfluff_config(self) -> Path:
        return self.root / ".sqlfluff"

    @property
    def model(self) -> Path:
        return self.dab / "model.yaml"

    @property
    def uss(self) -> Path:
        return self.dab / "uss.yaml"

    @property
    def dar_sql(self) -> Path:
        return self.root / "dar" / "uss"

    @property
    def destination(self) -> Path:
        return self.root / "destinations" / "app.py"

    @property
    def screenshots(self) -> Path:
        return self.root / ".screenshots"

    @property
    def browser_cache(self) -> Path:
        return self.root / ".browsers"

    @property
    def connections(self) -> Path:
        return self.dab / "connections.yaml"

    @property
    def engine_binary(self) -> Path:
        return self.root / "bin" / "linux-amd64" / "daana-cli"

    def contract_paths(self) -> tuple[Path, ...]:
        return tuple(sorted(self.contracts.glob("*.yaml")))

def require_detached(path: Path, tool: str) -> None:
    """Refuse to invoke a separate process against a warehouse this one is holding."""
    if _open[path.absolute()]:
        raise WarehouseHeldError(HELD.format(path=path, tool=tool))


@contextmanager
def exclusive(path: Path) -> Iterator[duckdb.DuckDBPyConnection]:
    """Open the warehouse for writing, refusing rather than waiting if it is held."""
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        connection = duckdb.connect(str(path))
    except duckdb.IOException as busy:
        raise WarehouseBusyError(BUSY.format(path=path)) from busy
    _open[path.absolute()] += 1
    try:
        yield connection
    finally:
        connection.close()
        _open[path.absolute()] -= 1


@contextmanager
def reading(path: Path) -> Iterator[duckdb.DuckDBPyConnection]:
    """Open the warehouse read-only, which is how every destination opens it.

    A reader holding a writable handle blocks the next build, and the build is the thing
    that cannot be worked around.
    """
    try:
        connection = duckdb.connect(str(path), read_only=True)
    except duckdb.IOException as busy:
        raise WarehouseBusyError(BUSY.format(path=path)) from busy
    _open[path.absolute()] += 1
    try:
        yield connection
    finally:
        connection.close()
        _open[path.absolute()] -= 1


def statements(sql: str) -> list[str]:
    """Split generated SQL into executable statements.

    Every generated statement opens with a comment saying which artefact it came from, so
    "does not start with --" is exactly the wrong test: it would skip all of them.

    generated = {f"{model.entity(e).object_name}.sql": peripheral_sql(model, e) for e in named}
    generated["_bridge.sql"] = bridge_sql(model, uss)
    generated["_calendar.sql"] = calendar_sql()
    return {name: formatted(sql, project.sqlfluff_config) for name, sql in generated.items()}


def _generated_checks(project: Project) -> dict[str, str]:
    """The checks the model generates, as file name to SQL. The contracts generate the rest."""
    model = read_model(project.model)
    return {
        f"{name}.sql": formatted(sql, project.sqlfluff_config)
        for name, sql in relationship_checks(model).items()
    }


@dar.command("generate")
def dar_generate(
    check: Annotated[
        bool, typer.Option(help="Fail if what is committed is not what regenerates.")
    ] = False,
) -> None:
    """Write the star schema's SQL from the model and its declarations."""
    project = Project.discover()
    project.dar_sql.mkdir(parents=True, exist_ok=True)
    project.checks_sql.mkdir(parents=True, exist_ok=True)
    stale = False
    everything = {project.dar_sql / n: s for n, s in _generate(project).items()}
    everything |= {project.checks_sql / n: s for n, s in _generated_checks(project).items()}
    for written, sql in everything.items():
        if check:
            current = written.read_text() if written.exists() else ""
            if current != sql:
                typer.echo(f"{written.relative_to(project.root)} is not what the model generates")
                stale = True
            continue
        written.write_text(sql)
        typer.echo(f"wrote {written.relative_to(project.root)}")
    if stale:
        raise typer.Exit(1)


@dar.command("build")
def dar_build() -> None:
    """Run the generated SQL against the warehouse, peripherals first."""
    project = Project.discover()
    generated = _generate(project)
    ordered = [n for n in generated if n not in ("_bridge.sql", "_calendar.sql")]
    ordered += ["_bridge.sql", "_calendar.sql"]
    with exclusive(project.warehouse) as connection:
        connection.execute(f"CREATE SCHEMA IF NOT EXISTS {Schema.DAR_USS}")
        for name in ordered:
            # What was generated, not what is on disk. "Nothing here is hand-edited" is then
            # true by construction rather than by a check somebody has to run.
            install(connection, generated[name])
            typer.echo(f"built {name.removesuffix('.sql')}")

